  public function executeUpdate()
  {
    if (!$this->getRequestParameter('docprestamo_id'))
    {
      $doc_prestamo = new DocPrestamo();
    }
    else
    {
      $doc_prestamo = DocPrestamoPeer::retrieveByPk($this->getRequestParameter('docprestamo_id'));
      $this->forward404Unless($doc_prestamo);
    }

    //$doc_prestamo->setDocprestamoId($this->getRequestParameter('docprestamo_id'));
    $doc_prestamo->setRegionalId($this->getRequestParameter('regional_id') ? $this->getRequestParameter('regional_id') : null);
    $doc_prestamo->setPeriodoId($this->getRequestParameter('periodo_id') ? $this->getRequestParameter('periodo_id') : null);
    $doc_prestamo->setUsuarioId($this->getRequestParameter('usuario_id') ? $this->getRequestParameter('usuario_id') : null);
    $doc_prestamo->setDocestadoprestamoId($this->getRequestParameter('docestadoprestamo_id') ? $this->getRequestParameter('docestadoprestamo_id') : null);
    if ($this->getRequestParameter('fecha_prestamo'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_prestamo'), $this->getUser()->getCulture());
      $doc_prestamo->setFechaPrestamo("$y-$m-$d");
    }
    if ($this->getRequestParameter('fecha_vencimiento'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_vencimiento'), $this->getUser()->getCulture());
      $doc_prestamo->setFechaVencimiento("$y-$m-$d");
    }
    if ($this->getRequestParameter('fecha_devolucion'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_devolucion'), $this->getUser()->getCulture());
      $doc_prestamo->setFechaDevolucion("$y-$m-$d");
    }
    $doc_prestamo->setObservaciones($this->getRequestParameter('observaciones'));
    $doc_prestamo->setConsecutivoRegional($this->getRequestParameter('consecutivo_regional'));
    $doc_prestamo->setNumeroRadicacion($this->getRequestParameter('numero_radicacion'));

    $doc_prestamo->save();

    return $this->redirect($this->getRequest()->getScriptName().'/prestamo_documentacion/show?docprestamo_id='.$doc_prestamo->getDocprestamoId());
  }
  
