  public function executeDevolverTodos()
  {
  	/*******************************Cambiar Estado Del Prestamo****************************************************/
  	$prestamo = DocPrestamoPeer::retrieveByPK($this->getRequestParameter('docprestamo_id'));
  	$prestamo->setDocestadoprestamoId(2);
  	$prestamo->setFechaDevolucion(date("Y-m-d"));
  	$prestamo->save();
	/**************************************************************************************************************/  	
  	
  	/***********************Cambiar Estado De Los Detalles del Prestamo********************************************/
  	$c = new Criteria();
  	$c->add(DocDetallePrestamoPeer::DOCPRESTAMO_ID,$this->getRequestParameter('docprestamo_id'));
  	$c->add(DocDetallePrestamoPeer::DOCESTADOPRESTAMO_ID,1);
  	$prestados =  DocDetallePrestamoPeer::doSelect($c);
	foreach($prestados as $result){
		$result->setDocestadoprestamoId(2);		
		$result->save();
	}    
	/**************************************************************************************************************/
	//$this->redirect('prestamo/show?prestamo_id='.$prestamo->getPrestamoId());
	$this->redirect('prestamo_documentacion/show?docprestamo_id='.$this->getRequestParameter('docprestamo_id'));	
  }
  
  public function executeUpdateDevolver()
  {   	 	
  	/************************Cambio Estado de la solicitud en la tabla DocDetallePrestamo***************************/
  	$c =  new Criteria();
  	$c->add(DocDetallePrestamoPeer::DOCSOLICITUDPRESTAMO_ID,$this->getRequestParameter('docsolicitudprestamo_id'));
  	$resp  = DocDetallePrestamoPeer::doSelectOne($c);  	  	
	$resp->setDocestadoprestamoId(2);
	$resp->save();
	/**************************************************************************************************************/			
	/***********************Verifica Estado de la solicitud Para asi Cambiar estado del Prestamo*******************/
	$a = new Criteria();
	$a->add(DocDetallePrestamoPeer::DOCPRESTAMO_ID,$this->getRequestParameter('docprestamo_id'));
	$a->add(DocDetallePrestamoPeer::DOCESTADOPRESTAMO_ID,1);
	$temp = DocDetallePrestamoPeer::doCount($a);
	if($temp == 0){		
		$prestamo = DocPrestamoPeer::retrieveByPK($this->getRequestParameter('docprestamo_id'));
		$prestamo->setDocestadoprestamoId(2);
		$prestamo->setFechaDevolucion(date("Y-m-d"));
		$prestamo->save();
	}	
	/**************************************************************************************************************/
	$this->redirect('prestamo_documentacion/show?docprestamo_id='.$this->getRequestParameter('docprestamo_id'));		
  }
  
  public function executeMail()
  {
  	$c  = new Criteria();
  	$parametros = '';
  	/**************************************************************************************************************/
	if($this->getRequestParameter('vencidos')){
		$c->setDistinct();
		$c->addJoin(DocPrestamoPeer::DOCPRESTAMO_ID,DocDetallePrestamoPeer::DOCPRESTAMO_ID);						
		$c->add(DocPrestamoPeer::FECHA_VENCIMIENTO, $this->getRequestParameter('vencidos'),Criteria::LESS_THAN);
		//$c->add(PrestamoPeer::FECHA_DEVOLUCION,$this->getRequestParameter('vencidos') ,Criteria::LESS_THAN);
		$c->add(DocDetallePrestamoPeer::DOCESTADOPRESTAMO_ID,1);
		$parametros .= "&vencidos=".$this->getRequestParameter('vencidos');								
	}
	/**************************************************************************************************************/
	$c->addAscendingOrderByColumn(DocPrestamoPeer::DOCPRESTAMO_ID);
	$resp          = DocPrestamoPeer::doSelect($c);
	$parametro     = ParametroPeer::retrieveByPK(43);
	$cuerpo        = $parametro->getValortexto();
	$datos  = array();
	$cuenta = array();
	$nomb = array();
	$texto ='';
	$e_mail='';
	foreach($resp as $resul){
		$a = new Criteria();
		$a->add(DocDetallePrestamoPeer::DOCPRESTAMO_ID,$resul->getDocprestamoId());
		$a->add(DocDetallePrestamoPeer::DOCESTADOPRESTAMO_ID,1);
		$obj = DocDetallePrestamoPeer::doSelect($a);
		$texto ='';
		$e_mail='';
		foreach($obj as $detalle){
		  $texto .= $detalle->getDocSolicitudPrestamo()->getdocumentacionId().'-'.$detalle->getDocSolicitudPrestamo()->getDocumentacion()->getTitulo().', ';
		  $e_mail = $detalle->getDocSolicitudPrestamo()->getUsuario()->getEmail();
		  $user = $detalle->getDocSolicitudPrestamo()->getUsuario(); 	
		}
		$datos[]  = $cuerpo.$texto;
		$cuenta[] = $e_mail;
		$nomb[]	= $user;
		//*********************************************************************************************************************
		$baseMail = new BaseMailSimad();
		$baseMail->SetSubject('CAD : Prestamo Documentacion Tecnica');
		$baseMail->SetMsgHTML($cuerpo.$texto);
		$baseMail->SetAddAddress($e_mail, $e_mail);    
		if($baseMail->InitSend() === true)
		{
		   $baseMail->writetolog("Alerta enviada: " . $e_mail . " Enviado a: " . $e_mail);
		}else{
		   $baseMail->writetolog("Error al enviar alerta: " . $e_mail . " Cuenta correo: " . $e_mail);
		}
		//***********************************************************************************************************************
	}	
	$this->datos = $datos;
	$this->cuenta = $cuenta;										
	$this->nomb = $nomb;
	/**************************************************************************************************************/
  }
  
