	if($this->getRequestParameter('usuario_id')){		
		$c->addJoin(DocPrestamoPeer::DOCPRESTAMO_ID, DocDetallePrestamoPeer::DOCPRESTAMO_ID);
	    $c->addJoin(DocDetallePrestamoPeer::DOCSOLICITUDPRESTAMO_ID, DocSolicitudPrestamoPeer::DOCSOLICITUDPRESTAMO_ID);
	    $c->add(DocSolicitudPrestamoPeer::USUARIO_ID,$this->getRequestParameter('usuario_id'));
		$parametros .= "&usuario_id=".$this->getRequestParameter('usuario_id');		
	}
	/**************************************************************************************************************/
	if($this->getRequestParameter('regional_id')){
		$c->add(DocPrestamoPeer::REGIONAL_ID, $this->getRequestParameter('regional_id'));
		$parametros .= "&regional_id=".$this->getRequestParameter('regional_id');		
	}
	//**************************************************************************************************************/
	if($this->getRequestParameter('dependencia_id')){			
		$c->addJoin(DocPrestamoPeer::USUARIO_ID, UsuarioPeer::USUARIO_ID);
	    $c->addJoin(UsuarioPeer::DEPENDENCIA_ID, DependenciaPeer::DEPENDENCIA_ID);
	    $c->add(DependenciaPeer::DEPENDENCIA_ID,$this->getRequestParameter('dependencia_id'));
		$parametros .= "&dependencia_id=".$this->getRequestParameter('dependencia_id');			
	}
	//**************************************************************************************************************/
	if($this->getRequestParameter('doc_estado_prestamo_id')){
		$c->add(DocPrestamoPeer::DOCESTADOPRESTAMO_ID, $this->getRequestParameter('doc_estado_prestamo_id'));
		$parametros .= "&doc_estado_prestamo_id=".$this->getRequestParameter('doc_estado_prestamo_id');		
	}
	//**************************************************************************************************************/
	if ($this->getRequestParameter('fechaInicial')) {
		if ($this->getRequestParameter('fechaFinal')) {
            $c->add(DocPrestamoPeer::FECHA_PRESTAMO,$this->getRequestParameter('fechaInicial'),Criteria::GREATER_THAN);
            $c->addAnd(DocPrestamoPeer::FECHA_PRESTAMO,$this->getRequestParameter('fechaFinal'),Criteria::LESS_THAN);
            $this->parametros .= "&fechaInicial=" . $this->getRequestParameter('fechaInicial');
        }else{
		    $c->add(DocPrestamoPeer::FECHA_PRESTAMO,$this->getRequestParameter('fechaInicial'),Criteria::GREATER_THAN);
		    $this->parametros .= "&fechaInicial=" . $this->getRequestParameter('fechaInicial');
	    }
    }	    	    
	//**************************************************************************************************************/
	if($this->getRequestParameter('ubicacionDoc')){			
		$c->addJoin(DocPrestamoPeer::DOCPRESTAMO_ID, DocDetallePrestamoPeer::DOCPRESTAMO_ID);
	    $c->addJoin(DocDetallePrestamoPeer::DOCSOLICITUDPRESTAMO_ID,DocSolicitudPrestamoPeer::DOCSOLICITUDPRESTAMO_ID);
	    $c->addJoin(DocSolicitudPrestamoPeer::DOCUMENTACION_ID, DocumentacionPeer::DOCUMENTACION_ID);
		$c->addJoin(DocumentacionPeer::UBICACION,$this->getRequestParameter('ubicacionDoc')) ;	    	    
		$parametros .= "&ubicacionDoc=".$this->getRequestParameter('ubicacionDoc');			
	}
	//**************************************************************************************************************/
	if($this->getRequestParameter('inventariador')){			
		$c->addJoin(DocPrestamoPeer::DOCPRESTAMO_ID, DocDetallePrestamoPeer::DOCPRESTAMO_ID);
	    $c->addJoin(DocDetallePrestamoPeer::DOCSOLICITUDPRESTAMO_ID, DocSolicitudPrestamoPeer::DOCSOLICITUDPRESTAMO_ID);
	    $c->addJoin(DocSolicitudPrestamoPeer::DOCUMENTACION_ID, DocumentacionPeer::DOCUMENTACION_ID);
		$c->addJoin(DocumentacionPeer::DOCUMENTACION_ID, UdUsuarioDocumentacionPeer::DOCUMENTACION_ID);	    
	    $c->add(UdUsuarioDocumentacionPeer::USUARIO_ID,$this->getRequestParameter('inventariador'));
	    $c->add(UdUsuarioDocumentacionPeer::RUSUARIODOCUMENTACION_ID,2);
		$parametros .= "&inventariador=".$this->getRequestParameter('inventariador');			
	}
	//**************************************************************************************************************/
	if($this->getRequestParameter('prestadoPor')){
		$c->add(DocPrestamoPeer::USUARIO_ID, $this->getRequestParameter('prestadoPor'));
		$parametros .= "&prestadoPor=".$this->getRequestParameter('prestadoPor');		
	}
	//**************************************************************************************************************/
	if($this->getRequestParameter('vencidos')?true:false){
		$c->addJoin(DocPrestamoPeer::DOCPRESTAMO_ID,DocDetallePrestamoPeer::DOCPRESTAMO_ID);						
		$c->add(DocPrestamoPeer::FECHA_VENCIMIENTO, $this->getRequestParameter('vencidos'),Criteria::LESS_THAN);
		$c->add(DocPrestamoPeer::FECHA_DEVOLUCION,$this->getRequestParameter('vencidos') ,Criteria::LESS_THAN);
		$c->add(DocDetallePrestamoPeer::DOCESTADOPRESTAMO_ID,1);
		$parametros .= "&vencidos=".$this->getRequestParameter('vencidos');								
	}
    //**************************************************************************************************************/	
	$c->addDescendingOrderByColumn(DocDetallePrestamoPeer::DOCPRESTAMO_ID);
    $this->pager = DocDetallePrestamoPeer::doSelect($c);
    $this->parametros = $parametros;    
	//*************************************************************************************************************/
  }
  
  public function executeDelete()
  {
    $doc_prestamo = DocPrestamoPeer::retrieveByPk($this->getRequestParameter('docprestamo_id'));
    $this->forward404Unless($doc_prestamo);
    $doc_prestamo->delete();
    return $this->redirect($this->getRequest()->getScriptName().'/prestamo_documentacion/list');
  }
}
